/* ============================================================
   OffLecture — SQL for Data Science
   HR Database Setup (SQL Server / SSMS dialect, dbo schema)
   Medium dataset: 10,000 employees · 15 departments · 20 jobs
                   75 projects · 2,500 assignments
   Canonical rows (emp 101-108, depts 1-4, jobs 1-4, P1-P4) preserved.
   ============================================================ */

IF OBJECT_ID('dbo.ASSIGNMENTS','U') IS NOT NULL DROP TABLE dbo.ASSIGNMENTS;
IF OBJECT_ID('dbo.PROJECTS','U')   IS NOT NULL DROP TABLE dbo.PROJECTS;
IF OBJECT_ID('dbo.EMPLOYEES','U')  IS NOT NULL DROP TABLE dbo.EMPLOYEES;
IF OBJECT_ID('dbo.JOBS','U')       IS NOT NULL DROP TABLE dbo.JOBS;
IF OBJECT_ID('dbo.DEPARTMENTS','U')IS NOT NULL DROP TABLE dbo.DEPARTMENTS;
GO

CREATE TABLE dbo.DEPARTMENTS (
    dept_id   INT          PRIMARY KEY,
    dept_name VARCHAR(50)  NOT NULL,
    location  VARCHAR(50)  NOT NULL
);
CREATE TABLE dbo.JOBS (
    job_id     INT          PRIMARY KEY,
    job_title  VARCHAR(50)  NOT NULL,
    min_salary INT          NOT NULL
);
CREATE TABLE dbo.EMPLOYEES (
    emp_id    INT          PRIMARY KEY,
    name      VARCHAR(80)  NOT NULL,
    dept_id   INT          NOT NULL REFERENCES dbo.DEPARTMENTS(dept_id),
    job_id    INT          NOT NULL REFERENCES dbo.JOBS(job_id),
    salary    INT          NOT NULL,
    hire_date DATE         NOT NULL
);
CREATE TABLE dbo.PROJECTS (
    project_id   VARCHAR(10) PRIMARY KEY,
    project_name VARCHAR(50) NOT NULL,
    dept_id      INT         NOT NULL REFERENCES dbo.DEPARTMENTS(dept_id),
    budget       INT         NOT NULL
);
CREATE TABLE dbo.ASSIGNMENTS (
    emp_id     INT         NOT NULL REFERENCES dbo.EMPLOYEES(emp_id),
    project_id VARCHAR(10) NOT NULL REFERENCES dbo.PROJECTS(project_id),
    hours      INT         NOT NULL,
    CONSTRAINT PK_ASSIGNMENTS PRIMARY KEY (emp_id, project_id)
);
GO

